 public static string Hash(string file){using(var s=File.OpenRead(file))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 public static string RandomKey(){var b=new byte[32];using(var r=RandomNumberGenerator.Create())r.GetBytes(b);return Convert.ToBase64String(b).TrimEnd('=').Replace('+','-').Replace('/','_');}
 public static Dictionary<string,object> Read(string p){return Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(p));}
 public static void PrivateDirectory(string p){Directory.CreateDirectory(p);CheckPath(p);var acl=new DirectorySecurity();acl.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WindowsIdentity.GetCurrent().User,new SecurityIdentifier("S-1-5-18")})acl.AddAccessRule(new FileSystemAccessRule(sid,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(p,acl);}
 public static void CheckPath(string p){string x=Path.GetFullPath(p);if(x.TrimEnd('\\')==Path.GetPathRoot(x).TrimEnd('\\'))throw new Exception("A drive root is not an application folder");for(string t=x;!String.IsNullOrEmpty(t);t=Path.GetDirectoryName(t)){if(Directory.Exists(t)&&(File.GetAttributes(t)&FileAttributes.ReparsePoint)!=0)throw new Exception("Linked installation/data paths are not supported");}}
 public static Dictionary<string,object> Secrets(string data){string p=Path.Combine(data,"credentials.dpapi");if(!File.Exists(p))return new Dictionary<string,object>();string s=File.ReadAllText(p);if(!s.StartsWith("dpapi:"))throw new Exception("Unencrypted credentials refused");return Json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(s.Substring(6)),null,DataProtectionScope.CurrentUser)));}
 public static void SaveSecrets(string data,Dictionary<string,object> s){PrivateDirectory(data);string p=Path.Combine(data,"credentials.dpapi");if(File.Exists(p))File.Copy(p,p+".before-"+DateTime.UtcNow.Ticks);File.WriteAllText(p,"dpapi:"+Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(Json.Serialize(s)),null,DataProtectionScope.CurrentUser)),new UTF8Encoding(false));}
 public static string Node(string install,string script,string arg,string input){var si=new ProcessStartInfo(Path.Combine(install,"runtimes","node","node.exe"),Q(Path.Combine(install,script))+" "+(String.IsNullOrEmpty(arg)?"":Q(arg))){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,RedirectStandardInput=true,WorkingDirectory=install};si.EnvironmentVariables["PYTHONDONTWRITEBYTECODE"]="1";si.EnvironmentVariables["PATH"]=Path.Combine(install,"runtimes","node")+";"+si.EnvironmentVariables["PATH"];using(var p=Process.Start(si)){var err=p.StandardError.ReadToEndAsync();var read=p.StandardOutput.ReadToEndAsync();if(input!=null)p.StandardInput.Write(input);p.StandardInput.Close();if(!p.WaitForExit(180000)){p.Kill();throw new Exception("Setup timed out. Inspect configuration before retrying; external resource creation may need reconciliation.");}string output=read.Result.Trim();if(String.IsNullOrEmpty(output))throw new Exception("Local component failed. Check runtime files and Windows permissions.");return output;}}
 public static void StartBackground(string install,string data){string paused=Path.Combine(data,"paused");if(File.Exists(paused))File.Delete(paused);Process.Start(new ProcessStartInfo(Path.Combine(install,"YGPTLocal.exe"),"--background --data-dir "+Q(data)){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});}
 public static Dictionary<string,object> LocalRequest(string data,string route,bool post){var c=Read(Path.Combine(data,"ygpt.config.json"));var s=Secrets(data);var req=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:"+Convert.ToString(c["port"])+route);req.Timeout=15000;req.Headers["Authorization"]="Bearer "+s["localKey"];if(post){req.Method="POST";req.ContentLength=0;}using(var r=req.GetResponse())using(var reader=new StreamReader(r.GetResponseStream()))return Json.Deserialize<Dictionary<string,object>>(reader.ReadToEnd());}
 public static bool IsOwnService(string data,int port){try{var c=Read(Path.Combine(data,"ygpt.config.json"));return Convert.ToInt32(c["port"])==port&&Convert.ToString(LocalRequest(data,"/healthz",false)["product"])=="YGPT Local";}catch{return false;}}
 public static void StopForMaintenance(string data){if(!File.Exists(Path.Combine(data,"ygpt.config.json")))return;bool connected=false;try{LocalRequest(data,"/healthz",false);connected=true;}catch(WebException ex){if(ex.Status!=WebExceptionStatus.ConnectFailure)throw new Exception("Could not confirm the existing local service identity. Close active tasks and retry.");}
  if(connected){var r=LocalRequest(data,"/maintenance/drain",true);if(!(bool)r["safeToStop"])throw new Exception("Finish owned tasks and pending approvals before maintenance.");}File.WriteAllText(Path.Combine(data,"paused"),"owner maintenance");
  for(int i=0;i<150;i++){bool stopped=false;try{var p=Path.Combine(data,"service-health.json");stopped=File.Exists(p)&&Read(p).ContainsKey("stopped")&&(bool)Read(p)["stopped"];}catch{}if(stopped||!connected){Thread.Sleep(1200);return;}Thread.Sleep(200);}throw new Exception("The existing service has not stopped safely. No application files were replaced.");}
 public static void Background(string data){bool created;using(var mutex=new Mutex(true,"Local\\YGPTLocal-"+Convert.ToBase64String(Encoding.UTF8.GetBytes(Path.GetFullPath(data))).Replace('\\','_').Replace('/','_'),out created)){if(!created)return;string paused=Path.Combine(data,"paused");F.NotifyIcon tray=new F.NotifyIcon{Icon=System.Drawing.SystemIcons.Application,Text="YGPT Local",Visible=true};var menu=new F.ContextMenuStrip();menu.Items.Add("Open setup",null,(s,e)=>Process.Start(new ProcessStartInfo(Path.Combine(Base,"YGPTLocal.exe"),"--data-dir "+Q(data)){UseShellExecute=true}));menu.Items.Add("Pause local service",null,(s,e)=>File.WriteAllText(paused,"paused by owner"));tray.ContextMenuStrip=menu;tray.DoubleClick+=(s,e)=>Process.Start(new ProcessStartInfo(Path.Combine(Base,"YGPTLocal.exe"),"--data-dir "+Q(data)){UseShellExecute=true});
  var thread=new Thread(()=>{try{while(!File.Exists(paused)){var si=new ProcessStartInfo(Path.Combine(Base,"runtimes","node","node.exe"),Q(Path.Combine(Base,"service","supervisor.mjs"))+" "+Q(data)){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,WorkingDirectory=Base};si.EnvironmentVariables["PATH"]=Path.Combine(Base,"runtimes","node")+";"+si.EnvironmentVariables["PATH"];using(var p=Process.Start(si)){p.WaitForExit();}if(!File.Exists(paused))Thread.Sleep(5000);}}finally{tray.Visible=false;tray.Dispose();F.Application.Exit();}});thread.IsBackground=true;thread.Start();F.Application.Run();}}
 public static void Shortcut(string install,string data){string p=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu),"Programs","YGPT Local.lnk");object shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));object link=shell.GetType().InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{p});var t=link.GetType();t.InvokeMember("TargetPath",BindingFlags.SetProperty,null,link,new object[]{Path.Combine(install,"YGPTLocal.exe")});t.InvokeMember("Arguments",BindingFlags.SetProperty,null,link,new object[]{"--data-dir "+Q(data)});t.InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);}
