  if(step==0){Text("Connect ChatGPT to your Windows PC.",20,true);Text("Read, edit and search local files, with protected file snapshots and clear approval for high-risk work. This setup installs one application and helps you connect your personal ChatGPT plugin.");Text("No OpenAI API key is required for the Cloudflare connection. Secure MCP Tunnel has separate account eligibility and runtime credentials.");ShowField("install","Application folder");ShowField("folder","Choose the folder you authorize for local work",true);body.Children.Add(consent);}
  if(step==1){Text(Environment.Is64BitOperatingSystem?"✓  64-bit Windows detected":"Unsupported: 64-bit Windows is required",16,true);Text("Node.js, embedded Python, cloudflared and the official OpenAI tunnel-client are included in the complete installer. You do not need to install developer tools.");ShowField("port","Private loopback port");Text("The service binds only to 127.0.0.1. No firewall rules or other services will be changed. Existing installations and tunnels keep their identity.");Text("Existing tunnel processes: "+Process.GetProcessesByName("tunnel-client").Length+". Use a dedicated NEW connection for this installation.");body.Children.Add(startup);}
  if(step==2){Text("Choose how ChatGPT will reach this PC. A public HTTPS connection always requires owner authentication.");ShowConnectionChoices();if(mode.SelectedIndex==0)ShowField("origin","Your existing tunnel's stable HTTPS address");if(mode.SelectedIndex==1){ShowField("hostname","New hostname in your Cloudflare zone");ShowField("account","Cloudflare account ID");ShowField("zone","Cloudflare zone ID");body.Children.Add(createConsent);}if(mode.SelectedIndex==2){ShowField("tunnel","Dedicated Secure MCP tunnel ID");ShowField("client","Override bundled official tunnel-client.exe (optional)");Text("Availability depends on your OpenAI account/workspace. The runtime key needs Tunnels Read + Use. Do not reuse your active production tunnel.");ActionButton("Open official tunnel setup",()=>Open("https://platform.openai.com/settings/organization/tunnels"));}if(mode.SelectedIndex==3)Text("This installs local components only. It will not be reported as connected to ChatGPT.");}
  if(step==3){Text("Secrets stay encrypted for your Windows user using DPAPI. They are not written to installation logs or sent to GitHub.");if(mode.SelectedIndex==0){Secret("token","Cloudflare connector token");Text("This runs an existing tunnel. It cannot create a new tunnel or DNS record. Route the hostname to http://127.0.0.1:"+fields["port"].Text+".");}if(mode.SelectedIndex==1){Secret("apiToken","Cloudflare API token");Text("Needs Cloudflare Tunnel Edit for the selected account and DNS Edit for the selected zone. It is distinct from a connector token.");}if(mode.SelectedIndex==2){Secret("runtimeKey","OpenAI API runtime key - Tunnels Read + Use");Text("This key authenticates the official OpenAI Tunnel client. A model-generation API call is not part of setup. Leave it blank during repair to keep the encrypted saved key.");ActionButton("Open OpenAI runtime key settings",()=>Open("https://platform.openai.com/settings/organization/api-keys"));}Text("An owner pairing key is generated locally for HTTPS OAuth connections. You will approve the connection in your own browser; this setup never signs into ChatGPT for you.");}
  if(step==4){Text("Ready to install",20,true);Text("Application: "+fields["install"].Text+"\nData: "+data+"\nWorking folder: "+fields["folder"].Text+"\nConnection: "+((ComboBoxItem)mode.SelectedItem).Content);Text("New installations use an empty dedicated folder. For an existing YGPT Local installation, setup drains owned work before repair/update and preserves the previous application folder. Settings and file snapshots stay in place. Existing YUKI installations are never replaced.");}
  if(step==5){Text("Check each stage independently. Installation alone does not prove a remote connection or a ChatGPT tool call.");ActionButton("Run connection checks",async()=>await Verify());ActionButton("Start service",()=>YGPTApp.StartBackground(install,data));ActionButton("Pause service",()=>YGPTApp.StopForMaintenance(data));ActionButton("Rotate local pairing credentials",()=>{YGPTApp.StopForMaintenance(data);var secure=YGPTApp.Secrets(data);secure["ownerKey"]=YGPTApp.RandomKey();secure["localKey"]=YGPTApp.RandomKey();secure["tunnelKey"]=YGPTApp.RandomKey();YGPTApp.SaveSecrets(data,secure);YGPTApp.StartBackground(install,data);message.Text="Local owner and transport keys rotated; reconnect existing clients. External API keys must be revoked at their provider.";});ActionButton("Revoke external API keys at provider",()=>Open(Mode()=="secure-tunnel"?"https://platform.openai.com/settings/organization/api-keys":"https://dash.cloudflare.com/profile/api-tokens"));ActionButton("Copy safe support summary",()=>Clipboard.SetText("YGPT Local "+YGPTApp.Version+"\nWindows "+Environment.OSVersion.Version+"\n"+message.Text));ActionButton("Uninstall application (keep data)",Uninstall);}
  if(step==6){Text("Finish in ChatGPT",20,true);Text("1. Open ChatGPT Plugins → + → Add custom MCP server.\n2. Name it YGPT Local. Enter the HTTPS endpoint or select your Secure MCP Tunnel.\n3. Choose OAuth for HTTPS, review the risk warning, then create and install the personal plugin.\n4. In a new chat select @YGPT Local and ask it to list your authorized test folder.");ActionButton("Open ChatGPT Plugins",()=>Open("https://chatgpt.com/plugins"));ActionButton("Copy plugin name",()=>Clipboard.SetText("YGPT Local"));ActionButton("Copy endpoint / tunnel ID",()=>{var x=YGPTApp.Read(Path.Combine(data,"connection.json"));Clipboard.SetText(x.ContainsKey("publicOrigin")&&x["publicOrigin"]!=null?(string)x["publicOrigin"]+"/mcp":Convert.ToString(x["tunnelId"]));});ActionButton("Copy owner pairing key (never paste in chat)",()=>{var x=YGPTApp.Secrets(data);Clipboard.SetText((string)x["ownerKey"]);message.Text="Pairing key copied for the OAuth approval page. Keep it private.";});ActionButton("Check client callback",async()=>await Verify());Text("The official interface still requires your confirmation. YGPT Local does not use private ChatGPT APIs or claim to create a plugin without a verified callback.");}
 }
 async void Next(object sender,RoutedEventArgs e){if(busy)return;try{if(step==0){if(consent.IsChecked!=true)throw new Exception("Please review and confirm local access before installing.");if(!Directory.Exists(fields["folder"].Text))throw new Exception("Choose an existing working folder.");YGPTApp.CheckPath(fields["install"].Text);}if(step==1){int p;if(!Int32.TryParse(fields["port"].Text,out p)||p<1024||p>65535)throw new Exception("Choose a port from 1024 to 65535.");if(!YGPTApp.IsOwnService(data,p)){var check=new TcpListener(IPAddress.Loopback,p);try{check.Start();}finally{check.Stop();}}}if(step==2&&mode.SelectedIndex==1&&createConsent.IsChecked!=true)throw new Exception("Confirm creation of a dedicated tunnel and DNS record.");if(step==4){await Install();step=5;Render();return;}if(step==6){Close();return;}step++;Render();}catch(Exception ex){message.Text=ex.Message;}}
 async Task Install(){busy=true;next.IsEnabled=false;back.IsEnabled=false;message.Text="Installing and checking local components…";install=Path.GetFullPath(fields["install"].Text);try{await Task.Run(()=>{if(File.Exists(Path.Combine(install,".ygpt-install.json")))YGPTApp.StopForMaintenance(data);YGPTApp.InstallPayload(install);YGPTApp.PrivateDirectory(data);var secrets=YGPTApp.Secrets(data);if(!secrets.ContainsKey("ownerKey"))secrets["ownerKey"]=YGPTApp.RandomKey();if(!secrets.ContainsKey("localKey"))secrets["localKey"]=YGPTApp.RandomKey();if(!secrets.ContainsKey("tunnelKey"))secrets["tunnelKey"]=YGPTApp.RandomKey();Dispatcher.Invoke(()=>{foreach(var kv in passwords)if(kv.Value.Password.Length>0)secrets[kv.Key=="token"?"tunnelToken":kv.Key]=kv.Value.Password;});YGPTApp.SaveSecrets(data,secrets);Dictionary<string,object> settings=null;Dispatcher.Invoke(()=>settings=new Dictionary<string,object>{{"dataDir",data},{"projectRoot",fields["folder"].Text},{"port",Int32.Parse(fields["port"].Text)},{"mode",Mode()},{"publicOrigin",fields["origin"].Text},{"hostname",fields["hostname"].Text},{"accountId",fields["account"].Text},{"zoneId",fields["zone"].Text},{"tunnelId",fields["tunnel"].Text},{"autoStart",startup.IsChecked==true},{"confirmCreate",createConsent.IsChecked==true}});
   string optional=null;Dispatcher.Invoke(()=>optional=fields["client"].Text);if(!String.IsNullOrEmpty(optional)){if(Path.GetFileName(optional)!="tunnel-client.exe")throw new Exception("Select the official tunnel-client.exe");File.Copy(optional,Path.Combine(install,"runtimes","tunnel-client.exe"),true);}
   string output=YGPTApp.Node(install,"service/provision.mjs",null,YGPTApp.Json.Serialize(settings));var r=YGPTApp.Json.Deserialize<Dictionary<string,object>>(output);if(!(bool)r["ok"])throw new Exception(Convert.ToString(r["message"]));YGPTApp.Register(install,data,(bool)settings["autoStart"]);YGPTApp.StartBackground(install,data);
  });}finally{busy=false;next.IsEnabled=true;back.IsEnabled=true;}}
 async Task Verify(){try{message.Text="Checking local service…";string result=await Task.Run(()=>{var s=YGPTApp.Secrets(data);var c=YGPTApp.Read(Path.Combine(data,"ygpt.config.json"));var req=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:"+Convert.ToString(c["port"])+"/healthz");req.Headers["Authorization"]="Bearer "+s["localKey"];req.Timeout=10000;using(var response=req.GetResponse())using(var reader=new StreamReader(response.GetResponseStream()))return reader.ReadToEnd();});var h=YGPTApp.Json.Deserialize<Dictionary<string,object>>(result);message.Foreground=B("#176A53");message.Text="Tunnel / connection: "+YGPTApp.Json.Serialize(h["connection"])+"\nLocal Ready: "+h["localReady"]+"\nTool catalog: "+h["publicTools"]+" public + "+h["appOnly"]+" app-only\nAuthenticated client call received: "+h["hostLinked"]+"\nLast remote read: "+Convert.ToString(h["lastHostRead"])+"\nConfirm the corresponding tool result in ChatGPT. Local checks alone do not verify ChatGPT identity.";}catch(Exception ex){message.Foreground=B("#A13225");message.Text="Connection not verified. "+ex.Message+" Retry after checking your port, service and tunnel credentials.";}}
 public void Uninstall(){if(MessageBox.Show("Remove this YGPT Local application? Settings, encrypted credentials and file snapshots will be retained. Finish active tasks before continuing.","YGPT Local",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;install=Path.GetFullPath(install);YGPTApp.CheckPath(install);YGPTApp.StopForMaintenance(data);string helper=Path.Combine(Path.GetTempPath(),"YGPTLocal-Uninstall-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(Path.Combine(install,"YGPTLocal.exe"),helper);Process.Start(new ProcessStartInfo(helper,"--uninstall-worker --install-dir "+YGPTApp.Q(install)+" --data-dir "+YGPTApp.Q(data)){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});Close();}
 static void Open(string url){Process.Start(new ProcessStartInfo(url){UseShellExecute=true});}
}
